        'dress_code', jsonb_build_object('status','official_muted_functional_dark_closed_shoe_code_with_formal_high_heel_open_shoe_lightwear_exclusions_all_gender_toplessness_and_no_phone_rule','source_urls',to_jsonb(array['https://www.fuse.be/faq']::text[]),'checked_at','2026-08-06T00:00:00Z'),
