        'crowd_mix', jsonb_build_object('status','queer_regular_gay_man_mixed_lgbtq_friend_and_international_visitor_social_bar_mix_distinct_from_men_only_cruising','source_urls',to_jsonb(array['https://wanderlog.com/place/details/4177643/lhomoerectus-by-spit-it-out','https://whereis.gay/homoerectus-bar','https://localguide.brussels/en/spot/lhomo-erectus/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
