    (202::bigint, jsonb_build_object(
      'queue_wait', 'The wood-panelled room is genuinely small. Weekday afternoons are calm enough to claim a stool and talk; Friday, Saturday and Pride can fill it shoulder to shoulder, with spillover standing outside. There is rarely a club-style line, but capacity is the limit. The correct doorway is Petite Rue au Beurre 2A.',
      'best_nights', 'Come after work for coffee, advocaat or Belgian beer and stay while the oldies-to-pop soundtrack lifts. Friday and Saturday become louder and more communal; Eurovision and Pride turn history into a party. Quiet weekday daylight is better if you want the staff and old interior to tell their stories.',
      'crowd_mix', 'Mature gay men and bears remain the heart, joined by younger admirers, loyal locals, mixed-age LGBTQ+ friends and Grand-Place tourists. Recent reports show a broader welcome than the old stereotype. Weekdays lean neighbourhood; celebratory weekends bring city and visitors into one narrow room.',
      'dress_code', 'There is no style test at this classic Belgian tavern. Knitwear, checked shirts, tourist layers and a sharper Friday look all fit the stained glass and dark wood. Comfort matters because stools and passage space are tight. Arrive as yourself, order well and respect the regulars.',
      'staff_inclusivity', 'Current reviews under the newer team are strikingly warm: guests praise fast service, English-friendly conversation and hosts who turn a quick beer into an evening. Older reports describe abrupt treatment, especially toward women, but largely predate this team. Recent feedback still notes toilets needing care.',
      'venue_classification', 'active_historic_oldest_brussels_gay_tavern_at_petite_rue_au_beurre_with_preserved_wood_interior_belgian_beer_coffee_mature_bear_core_mixed_age_visitors_weekend_pop_and_current_warm_host_consensus',
      'identity_note', 'La Réserve is at Petite Rue au Beurre/Korte Boterstraat 2A, 1000 Brussels. The stored Rue de l’Évêque 21 address is incorrect. Current local tourism information names Sebastian and Benji as the hosts.',
      'source_urls', to_jsonb(array['https://www.visit.brussels/en/visitors/venue-details.La-Reserve.266669','https://www.la-reserve.brussels/','https://wanderlog.com/place/details/4639772/la-r%C3%A9serve','https://whereis.gay/listing/la-reserve/','https://www.travelgay.com/venue/la-reserve','https://brussels.gaycities.com/bars/303261-la-reserve','https://ket.brussels/2025/11/20/timeless-charm-at-la-reserve-brussels-oldest-gay-bar-welcomes-all/']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','small_room_weekday_calm_weekend_pride_capacity_without_typical_club_line_outside_spillover_and_correct_doorway','source_urls',to_jsonb(array['https://www.visit.brussels/en/visitors/venue-details.La-Reserve.266669','https://wanderlog.com/place/details/4639772/la-r%C3%A9serve','https://whereis.gay/listing/la-reserve/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','afterwork_coffee_advocaat_belgian_beer_weekend_pop_eurovision_pride_and_quiet_history_conversation_variation','source_urls',to_jsonb(array['https://wanderlog.com/place/details/4639772/la-r%C3%A9serve','https://whereis.gay/listing/la-reserve/','https://www.travelgay.com/venue/la-reserve']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','mature_gay_bear_core_younger_admirer_local_mixed_age_lgbtq_friend_and_grand_place_tourist_mix_with_time_shift','source_urls',to_jsonb(array['https://www.visit.brussels/en/visitors/venue-details.La-Reserve.266669','https://whereis.gay/listing/la-reserve/','https://www.travelgay.com/venue/la-reserve']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','no_style_test_classic_tavern_casual_checked_tourist_and_friday_looks_with_tight_room_comfort_and_regular_respect','source_urls',to_jsonb(array['https://ket.brussels/2025/11/20/timeless-charm-at-la-reserve-brussels-oldest-gay-bar-welcomes-all/','https://whereis.gay/listing/la-reserve/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','strong_current_fast_english_friendly_owner_host_praise_balanced_against_older_previous_management_women_hostility_and_current_toilet_care_note','source_urls',to_jsonb(array['https://wanderlog.com/place/details/4639772/la-r%C3%A9serve','https://whereis.gay/listing/la-reserve/','https://www.travelgay.com/venue/la-reserve']::text[]),'checked_at','2026-08-06T00:00:00Z')
