    (210::bigint, jsonb_build_object(
      'queue_wait', 'Sunday is the dependable queer night, when FLASH takes over YOU from 22:00. Entry is free before midnight with a €10 membership card; admission later costs €10. It becomes extremely packed, with toilet and cloakroom lines inside, so early entry buys comfort too. The venue is at Rue Duquesnoy 18.',
      'best_nights', 'Sunday is the reason to go: two rooms, pop and club tracks, visiting dancers or DJs and a late finish after central Brussels slows down. Arrive before midnight for a lighter, social opening; come later for maximum heat. Friday-Saturday listings are separate and not automatically the same queer party.',
      'crowd_mix', 'Mostly young gay and LGBTQ+ clubbers, local regulars and weekend visitors fill the floor, with women and allies admitted. It is mixed, but not especially lesbian-centred. Guests say expanded VIP zones squeeze general admission and weaken the communal feeling, so usable dance space feels small.',
      'dress_code', 'No clear fashion code is published for Sunday: contemporary clubwear, trainers and expressive queer looks are the practical norm. Bring cash for facilities, keep valuables close and expect weekly photographers. If privacy matters, ask where cameras work; this is not a phone-free or anonymous room.',
      'staff_inclusivity', 'Music, drag energy and visible queer freedom still win loyal praise. Recent reviews also allege aggressive security, weak conflict handling, language exclusion, paid toilets and VIP-first treatment; other guests felt welcomed. Go with friends and raise problems early rather than assuming a flawless safe-space response.',
      'venue_classification', 'active_weekly_sunday_flash_lgbtq_party_inside_you_night_club_at_duquesnoy_with_two_rooms_young_gay_queer_crowd_early_member_entry_late_capacity_pressure_photography_and_material_security_service_concerns',
      'identity_note', 'The recurring current identity is FLASH Club at YOU Night Club, 18 Rue Duquesnoy, 1000 Brussels. The stored Rue des Pierres 48 address is wrong, and the listing should present Sunday FLASH rather than imply one uniform all-week queer club.',
      'source_urls', to_jsonb(array['https://flashclub.be/en','https://wanderlog.com/place/details/5036016/flash-club','https://www.gayout.com/europe/belgium/brussels/bars/flash-club-1611','https://no.travelgay.com/venue/flash-tea-dance-you-night-club','https://www.thegayagenda.fyi/brussels/businesses/you-night-club/','https://fr.restaurantguru.com/FLASH-CLUB-Brussels']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','sunday_2200_flash_free_before_midnight_with_paid_membership_then_paid_entry_extreme_capacity_internal_facility_lines_and_correct_address','source_urls',to_jsonb(array['https://flashclub.be/en','https://wanderlog.com/place/details/5036016/flash-club','https://www.gayout.com/europe/belgium/brussels/bars/flash-club-1611']::text[]),'checked_at','2026-08-06T00:00:00Z'),
