        'crowd_mix', jsonb_build_object('status','mostly_young_gay_lgbtq_local_visitor_woman_ally_mix_not_lesbian_centred_with_vip_partition_and_usable_capacity_concerns','source_urls',to_jsonb(array['https://www.gayout.com/europe/belgium/brussels/bars/flash-club-1611','https://no.travelgay.com/venue/flash-tea-dance-you-night-club','https://wanderlog.com/place/details/5036016/flash-club']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','no_published_sunday_fashion_code_with_contemporary_club_trainer_expression_cash_facility_valuables_and_weekly_photographer_privacy_context','source_urls',to_jsonb(array['https://flashclub.be/en','https://www.gayout.com/europe/belgium/brussels/bars/flash-club-1611']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','queer_music_drag_and_expression_praise_balanced_against_repeated_current_security_conflict_language_paid_toilet_vip_and_safe_space_failure_allegations','source_urls',to_jsonb(array['https://wanderlog.com/place/details/5036016/flash-club','https://www.gayout.com/europe/belgium/brussels/bars/flash-club-1611','https://www.thegayagenda.fyi/brussels/businesses/you-night-club/']::text[]),'checked_at','2026-08-06T00:00:00Z')
