    (209::bigint, jsonb_build_object(
      'queue_wait', 'Do not queue at Boulevard Anspach 73 for Machito. That address is a protected sandwich shop, and no current venue, official channel, calendar or credible review trail matches this listing. Remove the pin before it sends queer visitors to an unrelated daytime business.',
      'best_nights', 'There is no verified programme because no Brussels nightlife venue called Machito can be tied to this address. For a real queer evening, use nearby Rue du Marché au Charbon listings with live calendars. Inventing a Friday or Saturday here would turn a database error into travel advice.',
      'crowd_mix', 'No local, tourist or LGBTQ+ crowd can honestly be described for this record. Evidence at the address belongs to a historic sandwich counter, not a queer bar. Any Machito rating should be quarantined until its origin is known, not merged with reviews for the real business in the building.',
      'dress_code', 'There is no Machito door and no dress policy. The address is tied to a casual daytime food counter, but that does not make it a substitute venue. Hide this page, preserve the audit trail and restore it only if a verifiable operator supplies a distinct name, address and current programme.',
      'staff_inclusivity', 'No Machito team can be evaluated because the entity cannot be verified. Reviews of another business at the address must not become queer-safety evidence. Editorial restraint protects users here: suppress the record now and create a fresh place only if independent identity evidence appears.',
      'venue_classification', 'invalid_unverified_brussels_nightlife_record_named_machito_at_address_belonging_to_protected_au_suisse_sandwich_business_with_no_operator_calendar_reviews_or_distinct_queer_venue_identity',
      'record_status', 'non_venue_unverified_identity_hide_from_search_maps_sitemap_city_counts_recommendations_and_venue_intelligence_scoring',
      'identity_note', 'No credible current evidence connects a Brussels venue called Machito to Boulevard Anspach 73. The protected premises at 73-75 are documented as Au Suisse, a historic sandwich business.',
      'source_urls', to_jsonb(array['https://monument.heritage.brussels/fr/buildings/30712','https://www.brusselslife.be/fr/au-suisse','https://www.brusselstimes.com/39018/10-places-to-go-out-in-the-pedestrian-zone','https://unilocal.fr/belgique/bruxelles/au-suisse']::text[]),
