    (204::bigint, jsonb_build_object(
      'queue_wait', 'There is no current nightclub queue: Spirito ended public club operations on 30 April 2026 and held a closing sale in May. Its old selective church line is history. Ignore the stored Rue de l’Escalier address and unofficial tickets; the former club stood at Rue de Stassart 18 in Ixelles.',
      'best_nights', 'The weekend ritual beneath stained glass has finished. Historically, commercial dance, electro, hip-hop and polished Saturday production made the church the spectacle. The owners spoke of reinvention, but no public club programme is confirmed, so there is no honest “best night” now.',
      'crowd_mix', 'In its club years, Spirito drew young polished locals, international guests, private-table groups and visitors curious about the church interior. Reviews called the crowd posh or showy; it was LGBTQ+-friendly rather than queer-centred. That mix is history after the April 2026 closure.',
      'dress_code', 'The former door leaned chic and selective: smart shirts and shoes were safer for men, while trainers, T-shirts and casual looks met inconsistent treatment. Those reports describe the old club only. There is no valid current dress code, and stale booking pages do not prove admission has resumed.',
      'staff_inclusivity', 'Past guests split between polished, helpful service and complaints about arbitrary dress rules, price and discriminatory selection. Wheelchair access was advertised for the ground floor and basement. With the club closed, that does not establish a current team; any successor needs a fresh review.',
      'venue_classification', 'closed_30_april_2026_former_luxury_nightclub_in_deconsecrated_ixelles_church_with_historic_commercial_electro_weekends_selective_chic_door_mixed_staff_reports_and_no_confirmed_successor_club',
      'record_status', 'closed_former_nightclub_hide_from_search_maps_sitemap_city_counts_recommendations_and_current_venue_intelligence_scoring_until_verified_successor_opens',
      'identity_note', 'Spirito ceased nightclub operations on 30 April 2026. Its real former address was Rue de Stassart 18, 1050 Ixelles; the stored Rue de l’Escalier 38 address is incorrect. The official site currently has no scheduled events.',
      'source_urls', to_jsonb(array['https://www.bruzz.be/actua/cultuurnieuws/brusselse-nachtclub-spirito-sluit-de-deuren-april-2026-2025-04-18','https://www.brusselstimes.com/belgium/1540755/brussels-spirito-nightclub-to-close-after-16-years-of-operation','https://www.brusselstimes.com/belgium/2058507/after-dark-brussels-might-be-sacrificed-due-to-a-game-of-compromise/','https://www.spiritobrussels.com/fr/','https://www.visit.brussels/nl/bezoekers/venue-details.Spirito-Brussels.263044','https://selfcity.be/discotheek/brussel/spirito/','https://app.wanderlog.com/place/details/1820392/le-spirito']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','confirmed_no_current_queue_after_30_april_2026_club_closure_and_may_sale_with_correct_former_stassart_address','source_urls',to_jsonb(array['https://www.bruzz.be/actua/cultuurnieuws/brusselse-nachtclub-spirito-sluit-de-deuren-april-2026-2025-04-18','https://www.brusselstimes.com/belgium/1540755/brussels-spirito-nightclub-to-close-after-16-years-of-operation','https://www.spiritobrussels.com/fr/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','historic_weekend_commercial_electro_hiphop_church_spectacle_but_no_confirmed_successor_or_current_public_programme','source_urls',to_jsonb(array['https://www.bruzz.be/actua/cultuurnieuws/brusselse-nachtclub-spirito-sluit-de-deuren-april-2026-2025-04-18','https://www.spiritobrussels.com/fr/','https://selfcity.be/discotheek/brussel/spirito/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','historic_young_polished_local_international_private_table_and_architecture_visitor_mix_lgbtq_friendly_not_queer_centred_and_not_current','source_urls',to_jsonb(array['https://selfcity.be/discotheek/brussel/spirito/','https://app.wanderlog.com/place/details/1820392/le-spirito']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','historic_selective_chic_male_shirt_shoe_and_inconsistent_trainer_casual_enforcement_with_no_valid_current_policy','source_urls',to_jsonb(array['https://selfcity.be/discotheek/brussel/spirito/','https://app.wanderlog.com/place/details/1820392/le-spirito']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','historic_professional_helpful_praise_balanced_against_arbitrary_dress_price_and_discrimination_complaints_plus_advertised_access_not_current_team','source_urls',to_jsonb(array['https://selfcity.be/discotheek/brussel/spirito/','https://app.wanderlog.com/place/details/1820392/le-spirito','https://www.visit.brussels/nl/bezoekers/venue-details.Spirito-Brussels.263044']::text[]),'checked_at','2026-08-06T00:00:00Z')
