    (206::bigint, jsonb_build_object(
      'queue_wait', 'Friday and Saturday are busy by 23:00 and can reach shoulder-to-shoulder capacity around midnight. Earlier weekdays are easier; Sunday starts at 15:00 and builds around its dress theme. Entry varies by event, so check the calendar rather than assuming free admission. The current door is Rue du Marché au Charbon 114.',
      'best_nights', 'Friday-Saturday bring the fullest bar, darkroom and late-night social energy. Thursday often turns naked; Sunday afternoon rotates naked or underwear themes and feels easier for first contact. Monday-Wednesday suit conversation, but destination visitors should choose the exact fetish or techno date.',
      'crowd_mix', 'This men-focused gay cruise bar draws bears, leather men, admirers and curious visitors from roughly their twenties to sixties. Locals and tourists mix freely, and the front bar can be more social than the dark area. It is not an all-gender queer club; each body or fetish theme shapes the room.',
      'dress_code', 'Ordinary nights suit jeans, a T-shirt, sportswear or leather; heat and limited space punish fussy layers. Naked and underwear dates mean exactly that, with a clothes check and confidence doing more than fashion. Bring essentials, read the event wording and never treat a sexual dress theme as consent.',
      'staff_inclusivity', 'Many visitors describe a playful team and attitude-free crowd, especially on Sunday. Others report denied tap water, abrupt service, poor ventilation, uneven cleanliness and weak responses to unwanted touching. Condoms and lube should be easy to find; if not, ask before entering the dark area.',
      'venue_classification', 'active_men_focused_gay_cruise_and_fetish_bar_at_new_charcoal_market_address_with_front_social_bar_darkroom_weekend_capacity_naked_underwear_events_bear_leather_age_mix_and_material_facility_service_variation',
      'identity_note', 'Stammbar is currently at Rue du Marché au Charbon/Kolenmarkt 114, 1000 Brussels. The stored Rue des Pierres 29 address is obsolete. Official hours run evenings Monday-Saturday plus Sunday afternoon.',
      'source_urls', to_jsonb(array['https://stammbarbxl.com/','https://stammbarbxl.com/contact/','https://stammbarbxl.com/category/events/','https://stammbarbxl.com/naked-underwear-61/','https://stammbarbxl.com/naked-night-6/','https://www.travelgay.com/venue/stammbar','https://wanderlog.com/place/details/2447764/stammbar','https://brussels.gaycities.com/bars/305872-stammbar','https://ket.brussels/2023/03/17/stammbar/']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','friday_saturday_2300_midnight_capacity_weekday_ease_sunday_afternoon_theme_event_specific_entry_and_correct_current_address','source_urls',to_jsonb(array['https://stammbarbxl.com/contact/','https://www.travelgay.com/venue/stammbar','https://wanderlog.com/place/details/2447764/stammbar']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','weekend_full_bar_darkroom_thursday_naked_sunday_afternoon_naked_underwear_and_quieter_weekday_social_variation','source_urls',to_jsonb(array['https://stammbarbxl.com/category/events/','https://stammbarbxl.com/naked-underwear-61/','https://stammbarbxl.com/naked-night-6/','https://www.travelgay.com/venue/stammbar']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','men_focused_gay_bear_leather_admirer_local_tourist_and_roughly_twenty_to_sixty_mix_with_social_front_and_cruise_back','source_urls',to_jsonb(array['https://www.travelgay.com/venue/stammbar','https://brussels.gaycities.com/bars/305872-stammbar','https://ket.brussels/2023/03/17/stammbar/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','ordinary_jean_tshirt_sports_leather_and_heat_practicality_with_exact_naked_underwear_theme_clothes_check_essentials_and_consent_boundary','source_urls',to_jsonb(array['https://stammbarbxl.com/naked-underwear-61/','https://stammbarbxl.com/naked-night-6/','https://www.travelgay.com/venue/stammbar']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','many_playful_welcoming_sunday_team_and_attitude_free_crowd_reports_balanced_against_water_service_ventilation_cleanliness_and_touching_response_concerns','source_urls',to_jsonb(array['https://wanderlog.com/place/details/2447764/stammbar','https://www.travelgay.com/venue/stammbar','https://brussels.gaycities.com/bars/305872-stammbar']::text[]),'checked_at','2026-08-06T00:00:00Z')
      ),
      'research_status', 'editorial_review_consensus','updated_at', '2026-08-06T00:00:00Z'
