    (208::bigint, jsonb_build_object(
      'queue_wait', 'An early drink is usually simple; ticketed drag guests and Friday-Saturday parties can pack the bar. Headline doors often open an hour before showtime and some dates cost around €10, with a free party later. Book when offered and arrive for the host, not halfway through. The address is Plattesteen 18/20.',
      'best_nights', 'Let the calendar choose: Drag Race viewings feel communal, Friday drag brings full performance energy, blind tests turn pop knowledge into chaos, and queer tango slows the room enough to meet people. Friday-Saturday run latest, but a free midweek culture night can feel more Brussels than generic dancing.',
      'crowd_mix', 'Young LGBTQIA+ locals, drag regulars, gender-diverse friends, queer women, newcomers and respectful allies make a broad mix. International visitors are common and many events work in French and English. The format matters: a viewing party, tango class and midnight DJ floor are socially different rooms.',
      'dress_code', 'There is no fashion gate. Everyday clothes, sequins, drag, gender-expansive looks and dance-ready shoes belong. The real code is behavioural: the charter rejects homophobia, transphobia, racism, fatphobia, ableism and slut-shaming. For shows, keep sightlines clear and bring cash if artists invite tips.',
      'staff_inclusivity', 'Most guests describe a cosy, super-queer room, friendly service and freedom across identities. A clear anti-discrimination charter supports removing harmful behaviour. Some reviews allege weak theft or safety handling and discourteous service, so the written promise still depends on consistent action when packed.',
      'venue_classification', 'active_central_broad_lgbtqia_event_bar_at_plattesteen_with_drag_viewings_pop_games_queer_tango_workshops_late_weekends_gender_diverse_local_international_crowd_formal_anti_discrimination_charter_and_mixed_incident_handling_reports',
      'identity_note', 'The Agenda is currently at Plattesteen 18/20, 1000 Brussels. The stored Rue des Brasseurs 5 address is incorrect. Its official programme and opening hours are current through August 2026.',
      'source_urls', to_jsonb(array['https://theagendabxl.be/','https://theagendabxl.be/events/','https://theagendabxl.be/charter/','https://theagendabxl.be/about-us/','https://theagendabxl.be/events/drag-show-kerri/','https://theagendabxl.be/events/tango-practice/','https://theagendabxl.be/events/just-the-tip/','https://www.thegayagenda.fyi/brussels/businesses/the-agenda/','https://restaurantguru.com/The-Agenda-Brussels','https://ket.brussels/2026/02/24/cut-cut-funding-party-drag-community-and-a-brand-new-chest-at-the-agenda/']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','ordinary_early_walkin_ticketed_drag_and_weekend_capacity_typical_predoor_paid_show_later_free_party_advance_booking_and_correct_address','source_urls',to_jsonb(array['https://theagendabxl.be/','https://theagendabxl.be/events/drag-show-kerri/','https://theagendabxl.be/events/just-the-tip/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','calendar_led_drag_race_viewing_friday_drag_blindtest_queer_tango_workshop_and_late_weekend_versus_midweek_culture_variation','source_urls',to_jsonb(array['https://theagendabxl.be/','https://theagendabxl.be/events/','https://theagendabxl.be/events/tango-practice/','https://theagendabxl.be/events/just-the-tip/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','young_lgbtqia_drag_gender_diverse_queer_woman_newcomer_ally_and_international_french_english_mix_changing_by_format','source_urls',to_jsonb(array['https://theagendabxl.be/','https://theagendabxl.be/about-us/','https://www.thegayagenda.fyi/brussels/businesses/the-agenda/','https://ket.brussels/2026/02/24/cut-cut-funding-party-drag-community-and-a-brand-new-chest-at-the-agenda/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','no_fashion_gate_with_everyday_sequin_drag_gender_expression_and_dance_style_under_explicit_broad_anti_discrimination_behaviour_charter','source_urls',to_jsonb(array['https://theagendabxl.be/charter/','https://theagendabxl.be/about-us/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','majority_cosy_queer_friendly_cross_identity_service_praise_and_formal_exclusion_policy_balanced_against_theft_safety_and_courtesy_handling_complaints','source_urls',to_jsonb(array['https://theagendabxl.be/charter/','https://www.thegayagenda.fyi/brussels/businesses/the-agenda/','https://restaurantguru.com/The-Agenda-Brussels']::text[]),'checked_at','2026-08-06T00:00:00Z')
      ),
      'research_status', 'editorial_review_consensus','updated_at', '2026-08-06T00:00:00Z'
